<?php declare(strict_types=1);use Kulturhus\Verein\Numbering;
$numberExample=static function(array $rule):string{try{$checked=$rule;$checked['width']=\Kulturhus\Verein\SettingsSchema::integer($rule['width'],1,9);$next=\Kulturhus\Verein\SettingsSchema::integer($rule['next'],1,999999999);$checked['date']=\Kulturhus\Verein\SettingsSchema::choice($rule['date'],['none','year','month']);return Numbering::format($checked,$next,date('Y-m-d'));}catch(DomainException){return 'Vorschau nach Korrektur der Eingaben';}};
?>
<form method="post" class="settings-form" data-settings-form><?= csrf().hidden('action','settings-save').hidden('section','numbers').hidden('version',$sv) ?>
<?php foreach(['invoice'=>'Rechnungen & Einnahmen','expense'=>'Ausgaben','member'=>'Mitgliedsnummern'] as $key=>$label):$rule=$sd[$key]; ?><section class="card" data-number-rule><div class="section-heading"><h2><?= $label ?></h2><output class="number-example" data-number-example><?= e($numberExample($rule)) ?></output></div><div class="form-grid">
<?php foreach(['prefix'=>['Präfix','text',30,''],'date'=>['Datum','select',['none'=>'Kein Datum','year'=>'Jahr','month'=>'Jahr und Monat'],'year'],'width'=>['Stellen der laufenden Nummer','integer',[1,9],6],'next'=>['Nächste laufende Nummer','integer',[1,999999999],1],'suffix'=>['Suffix','text',20,'']] as $f=>$field)settingsField($f,$field,$rule,'data['.$key.']'); ?></div></section><?php endforeach ?>
<section class="card"><p>Neue Belege bekommen ihre Nummer beim Speichern. Beiträge und Geldspenden verwenden den Rechnungsnummernkreis. Vorhandene Nummern bleiben unverändert; verwendete Werte können nicht erneut vergeben werden.</p><p>Bei einer neuen Mitgliedschaft bedeutet eine leere Mitgliedsnummer: automatisch vergeben. Der Zähler läuft auch über Jahreswechsel weiter; das Datum stammt aus dem Beleg- bzw. Eintrittsdatum.</p><div class="settings-actions"><a class="btn btn-outline theme-secondary button secondary" href="?view=settings&amp;tab=numbers">Verwerfen</a><button class="btn btn-solid theme-primary">Nummernkreise speichern</button></div></section></form>
